		while (Low <= High)
		{
			const int32 Mid = Low + ((High - Low) / 2);
			const int32 Compare = FCString::Strcmp(*Command, Entries[Mid].Command);
			if (Compare == 0)
			{
				ParseFields(Entries[Mid].CompactFields, OutCompactFields);
				ParseFields(Entries[Mid].ArtifactFields, OutArtifactFields);
				ParseFields(Entries[Mid].TruncateFields, OutMaxItemsPolicy.Fields);
				OutMaxItemsPolicy.DefaultMaxItems = Entries[Mid].DefaultMaxItems;
				OutMaxItemsPolicy.HardMaxItems = Entries[Mid].HardMaxItems;
				OutMaxItemsPolicy.PageField = Entries[Mid].PageField;
				return true;
			}
			if (Compare < 0)
			{
				High = Mid - 1;
			}
			else
			{
				Low = Mid + 1;
			}
		}
		OutCompactFields.Reset();
		OutArtifactFields.Reset();
		OutMaxItemsPolicy.Reset();
		return false;
